import axios from "axios";
import { defineStore } from "pinia";

export const useReviewsStore = defineStore("reviews", {
  state: () => {
    return {
      reviewsList: [],
    };
  },
  getters: {
    reviewsByProductId: (state) => {
      return (productId) => {
        return state.reviewsList.filter((e) => e.productId === productId);
      };
    },
  },
  actions: {
    async fetchReviews() {
      try {
        const res = await axios.get(
          "https://online-store-api-production-c30e.up.railway.app/reviews"
        );
        this.reviewsList = res.data;
      } catch (error) {
        console.log("could not fetch reviews", error);
      }
    },
    async postReview(newReview) {
      try {
        await axios.post("http://localhost:3000/reviews", newReview);
      } catch (error) {
        console.log("could not post the review", error);
      }
    },
  },
});
