<template>
  <div>
    <div v-if="product" class="product container m-auto row">
      <div class="info col-sm-12 col-md-6 m-0 p-2">
        <div class="product-image">
          <img class="mw-100" src="@/assets/6858344.jpg" alt="" />
        </div>
        <div class="name m-0 fw-bold">{{ product.name[locale] }}</div>
        <div class="disc m-0 text-primary">{{ product.disc[locale] }}</div>
        <div class="category m-0 text-success">
          {{ product.category[locale] }}
        </div>
        <div class="reviwes-rating d-flex gap-1 justify-content-end mt-2 mb-2">
          <div class="rate">
            <span
              ><i
                :class="['bi', 'bi-star-fill', { 'text-warning': rating >= 1 }]"
              ></i
            ></span>
            <span
              ><i
                :class="['bi', 'bi-star-fill', { 'text-warning': rating >= 2 }]"
              ></i
            ></span>
            <span
              ><i
                :class="['bi', 'bi-star-fill', { 'text-warning': rating >= 3 }]"
              ></i
            ></span>
            <span
              ><i
                :class="['bi', 'bi-star-fill', { 'text-warning': rating >= 4 }]"
              ></i
            ></span>
            <span
              ><i
                :class="['bi', 'bi-star-fill', { 'text-warning': rating >= 5 }]"
              ></i
            ></span>
          </div>
          <div class="reviews">reviews {{ reviewsList.length }}</div>
        </div>
        <span class="inStock bg-primary text-white fw-bold ps-1 pe-1 rounded-1">
          {{ product.inStock ? "in Stock" : "sold out" }}
        </span>
        <div class="dateAdded mt-2">{{ product.dateAdded }}</div>
        <div class="offers">{{ product.offer[locale] }}</div>
        <div class="price fs-4 fw-bold">{{ product.price }} $</div>
        <div class="buttons d-flex justify-content-between mt-2 mb-2">
          <button @click="addToCart()" class="btn btn-secondary">
            add to cart
          </button>
          <div class="d-flex">
            <button @click="changQuan('-')" class="btn btn-secondary">-</button>
            <input class="quan" type="text" v-model="quan" />
            <button @click="changQuan('+')" class="btn btn-secondary">+</button>
          </div>
        </div>
        <div class="tags">
          <span
            class="p-2 me-2 text-info"
            v-for="tag in product.tags"
            :key="tag"
            >#{{ tag }}</span
          >
        </div>
      </div>
      <div
        v-if="users.currentUser"
        class="reviews col-sm-12 col-md-6 d-flex flex-column justify-content-between ps-5"
      >
        <div class="reviews-list">
          <p class="fw-bold">Product Reviews</p>

          <div>
            <div
              class="p-1 rounded-2 bg-light mb-2"
              v-for="review in reviewsList"
              :key="review.id"
            >
              <p class="m-0">{{ review.comment }}</p>
              <p class="m-0 text-black-50">{{ review.date }}</p>
              <p class="m-0 text-black-50">{{ review.username }}</p>
            </div>
          </div>
        </div>
        <div class="form">
          <div class="rate-us">
            <span class="me-3">rate us</span>
            <span @click="rateProduct(1)"
              ><i
                role="button"
                :class="['bi', 'bi-star-fill', { 'text-warning': rate >= 1 }]"
              ></i
            ></span>
            <span @click="rateProduct(2)"
              ><i
                role="button"
                :class="['bi', 'bi-star-fill', { 'text-warning': rate >= 2 }]"
              ></i
            ></span>
            <span @click="rateProduct(3)"
              ><i
                role="button"
                :class="['bi', 'bi-star-fill', { 'text-warning': rate >= 3 }]"
              ></i
            ></span>
            <span @click="rateProduct(4)"
              ><i
                role="button"
                :class="['bi', 'bi-star-fill', { 'text-warning': rate >= 4 }]"
              ></i
            ></span>
            <span @click="rateProduct(5)"
              ><i
                role="button"
                :class="['bi', 'bi-star-fill', { 'text-warning': rate >= 5 }]"
              ></i
            ></span>
          </div>
          <div>
            <form action="">
              <label class="d-block" for="review">Write a comment</label>
              <input
                class="d-block mb-2"
                type="text"
                name="review"
                v-model="comment"
              />
              <button @click="submitReview()" class="btn btn-secondary">
                submit
              </button>
            </form>
          </div>
        </div>
      </div>
      <div
        v-else
        class="col-sm-12 col-md-6 d-flex flex-column justify-content-center align-items-center"
      >
        <p>sing in to see reviews</p>
        <button @click="headToSignPage()" class="btn btn-secondary">
          sign in
        </button>
