<script setup>
import { useI18n } from "vue-i18n";
const { locale } = useI18n();
import { useRoute, useRouter } from "vue-router";
import { useProductsStore } from "@/stores/products";
import { useReviewsStore } from "@/stores/reviews";
import { useUsersStore } from "@/stores/users";
import { useCartStore } from "@/stores/cart";
const cart = useCartStore();
const quan = ref(0);
import { computed, ref } from "vue";
const reviews = useReviewsStore();
const products = useProductsStore();
const users = useUsersStore();
const route = useRoute();
const router = useRouter();
//
const id = route.params.id;
const product = ref(products.getProductById(id));
console.log(products);
console.log(product);
if (!product.value) {
  fetchingPrduct(id);
}

async function fetchingPrduct(id) {
  await products.fetchProducts();
  product.value = products.getProductById(id);
}
const reviewsList = computed(() => reviews.reviewsByProductId(id));
if (!reviewsList.value) {
  loadReviews();
}
async function loadReviews() {
  await reviews.fetchReviews(); // ✅ هذا صحيح إذا كان fetchReviews() async
  reviewsList.value = reviews.reviewsByProductId(id);
}
//
const rate = ref(0); // new
const rating =
  reviewsList.value.reduce((sum, item) => sum + item.rating, 0) /
  reviewsList.value.length; // totall
const comment = ref("");
const now = new Date();
const currentDate = `${now.getDate()}/${now.getMonth()}/${now.getFullYear()}`;
// const userRate = ref(0);
function rateProduct(num) {
  return (rate.value = num);
}
async function submitReview() {
  if (rate.value && comment.value.trim().length > 0) {
    try {
      // 1. إضافة التقييم الجديد
      await reviews.postReview({
        productId: id,
        username: users.currentUser.username,
        rating: rate.value,
        comment: comment.value,
        date: currentDate,
      });

      // 2. إعادة جلب التقييمات
      await reviews.fetchReviews();

      // 3. تحديث المتوسط
      await products.patchproductsRating(id);

      // 4. إعادة تحميل بيانات المنتج
      await products.fetchProducts();
      product.value = products.getProductById(id);

      // 5. تفريغ الحقول
      rate.value = 0;
      comment.value = "";
    } catch (error) {
      console.error("Error submitting review:", error);
    }
  }
}
function headToSignPage() {
  router.push("/profile");
}
// cart function
function changQuan(sign) {
  if (sign === "-") {
    quan.value--;
  } else if (sign === "+") {
    quan.value++;
  }
}
//
function addToCart() {
  if (quan.value > 0) {
    cart.addToCart({
      id: product.value.id,
      name: product.value.name,
      quantity: quan.value,
      price: product.value.price,
    });
  }
}
</script>

