import { defineStore } from "pinia";

export const useCartStore = defineStore("cart", {
  state: () => {
    return {
      bill: [],
    };
  },
  getters: {
    totallQuantity: (state) => {
      return state.bill.reduce(
        (quan, item) => (quan = quan + item.quantity),
        0
      );
    },
    totallPrice: (state) => {
      return state.bill.reduce(
        (price, item) => (price = price + item.quantity * item.price),
        0
      );
    },
  },
  actions: {
    // الكود الحالي يعمل، لكن هذا أفضل:
    addToCart(product) {
      const existingItem = this.bill.find((item) => item.id === product.id);

      if (existingItem) {
        // استخدم الرقم 1 كافتراضي إذا لم توجد كمية
        existingItem.quantity += Number(product.quantity) || 1;
      } else {
        this.bill.push({
          ...product,
          quantity: product.quantity || 1, // تأكيد وجود كمية
        });
      }
    },
    removeItem(targetId) {
      this.bill = this.bill.filter((item) => item.id != targetId);
    },
  },
});
